import React, { useRef, useEffect, useState, useCallback } from 'react';
import * as d3 from 'd3';
import { DigoAsset } from '@digo-org/digo-api';

interface BarData {
  id: string;
  label: string;
  value: number;
  color: string;
}

interface RacingBarChartProps {
  instances: any[];
  globalParameters: Record<string, any>;
  timeArray: string[];
}

function RacingBarChart({ instances, globalParameters, timeArray }: RacingBarChartProps) {
  const svgRef = useRef<SVGSVGElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const [timeIndex, setTimeIndex] = useState(0);
  const [isPlaying, setIsPlaying] = useState(true);
  const intervalRef = useRef<number | null>(null);

  const bgColor = (globalParameters?.['background-color'] as string) || '#1a1a2e';
  const chartTitle = (globalParameters?.['chart-title'] as string) || 'CO2 Emissions by Country';
  const showTitle = globalParameters?.['show-title'] !== false;
  const barHeight = (globalParameters?.['bar-height'] as number) || 35;
  const barGap = (globalParameters?.['bar-gap'] as number) || 5;
  const animDuration = (globalParameters?.['animation-duration'] as number) || 500;

  const numTimeSteps = timeArray?.length || 0;
  const currentYear = timeArray?.[timeIndex] || '';

  // Auto-play timer
  useEffect(() => {
    if (isPlaying && numTimeSteps > 0) {
      intervalRef.current = window.setInterval(() => {
        setTimeIndex(prev => {
          const next = prev + 1;
          if (next >= numTimeSteps) {
            return 0;
          }
          return next;
        });
      }, animDuration + 800);
    }
    return () => {
      if (intervalRef.current !== null) {
        clearInterval(intervalRef.current);
        intervalRef.current = null;
      }
    };
  }, [isPlaying, numTimeSteps, animDuration]);

  // D3 chart update
  useEffect(() => {
    const svg = svgRef.current;
    const container = containerRef.current;
    if (!svg || !container) return;

    const width = container.clientWidth || 800;
    const height = container.clientHeight || 600;
    const margin = { top: showTitle ? 70 : 20, right: 130, bottom: 50, left: 20 };
    const innerWidth = width - margin.left - margin.right;
    const innerHeight = height - margin.top - margin.bottom;

    // Build sorted data
    const data: BarData[] = (instances || []).map((instance: any, i: number) => {
      const valuesArray = instance['co2-value'] as number[] | undefined;
      const currentValue = Array.isArray(valuesArray) ? (valuesArray[timeIndex] || 0) : 0;
      const label = (instance['bar-label'] as string) || 'Country ' + (i + 1);
      const color = (instance['bar-color'] as string) || d3.schemeTableau10[i % 10];
      return { id: instance.id || 'item-' + i, label, value: currentValue, color };
    }).sort((a, b) => b.value - a.value);

    const maxBars = Math.min(data.length, Math.floor(innerHeight / (barHeight + barGap)));
    const visibleData = data.slice(0, maxBars);
    const maxValue = d3.max(visibleData, d => d.value) || 1;

    const xScale = d3.scaleLinear().domain([0, maxValue * 1.05]).range([0, innerWidth]);
    const formatNumber = d3.format(',.0f');

    const svgSel = d3.select(svg).attr('width', width).attr('height', height);

    // Background
    svgSel.selectAll('.bg-rect').data([0]).join('rect')
      .attr('class', 'bg-rect')
      .attr('width', width).attr('height', height).attr('fill', bgColor);

    // Year watermark
    svgSel.selectAll('.year-watermark').data([currentYear]).join('text')
      .attr('class', 'year-watermark')
      .attr('x', width - margin.right - 10)
      .attr('y', height - 40)
      .attr('text-anchor', 'end')
      .attr('fill', 'rgba(255,255,255,0.06)')
      .attr('font-size', Math.min(width * 0.28, 220))
      .attr('font-weight', '900')
      .attr('font-family', 'Arial, sans-serif')
      .text(currentYear);

    // Title
    if (showTitle) {
      svgSel.selectAll('.chart-title').data([chartTitle]).join('text')
        .attr('class', 'chart-title')
        .attr('x', margin.left + 10).attr('y', 32)
        .attr('fill', '#ffffff').attr('font-size', 22)
        .attr('font-weight', '700').attr('font-family', 'Arial, sans-serif')
        .text(chartTitle);

      svgSel.selectAll('.year-label').data([currentYear]).join('text')
        .attr('class', 'year-label')
        .attr('x', margin.left + 10).attr('y', 55)
        .attr('fill', 'rgba(255,255,255,0.5)').attr('font-size', 15)
        .attr('font-family', 'Arial, sans-serif')
        .text('Year: ' + currentYear);
    } else {
      svgSel.selectAll('.chart-title').remove();
      svgSel.selectAll('.year-label').remove();
    }

    // Main group
    let mainGroup = svgSel.selectAll<SVGGElement, number>('.main-group').data([0]);
    const mainGroupMerged = mainGroup.enter().append('g').attr('class', 'main-group')
      .merge(mainGroup)
      .attr('transform', 'translate(' + margin.left + ',' + margin.top + ')');

    // --- BARS ---
    const bars = mainGroupMerged.selectAll<SVGRectElement, BarData>('.bar')
      .data(visibleData, d => d.id);

    bars.exit().transition().duration(animDuration / 2)
      .attr('width', 0).style('opacity', 0).remove();

    bars.enter()
      .append('rect').attr('class', 'bar')
      .attr('x', 0)
      .attr('y', (_d, i) => i * (barHeight + barGap))
      .attr('width', 0)
      .attr('height', barHeight)
      .attr('rx', 4).attr('ry', 4)
      .attr('fill', d => d.color)
      .merge(bars)
      .transition().duration(animDuration)
      .attr('y', (_d, i) => i * (barHeight + barGap))
      .attr('width', d => Math.max(0, xScale(d.value)))
      .attr('height', barHeight)
      .attr('fill', d => d.color);

    // --- LABELS (inside bars) ---
    const labels = mainGroupMerged.selectAll<SVGTextElement, BarData>('.bar-label')
      .data(visibleData, d => d.id);

    labels.exit().transition().duration(animDuration / 2).style('opacity', 0).remove();

    labels.enter()
      .append('text').attr('class', 'bar-label')
      .attr('x', 8)
      .attr('y', (_d, i) => i * (barHeight + barGap) + barHeight / 2)
      .attr('dy', '0.35em')
      .attr('fill', '#ffffff')
      .attr('font-size', Math.max(11, barHeight * 0.38))
      .attr('font-weight', '600')
      .attr('font-family', 'Arial, sans-serif')
      .style('opacity', 0)
      .merge(labels)
      .transition().duration(animDuration)
      .attr('y', (_d, i) => i * (barHeight + barGap) + barHeight / 2)
      .attr('font-size', Math.max(11, barHeight * 0.38))
      .style('opacity', 1)
      .text(d => d.label);

    // --- VALUE LABELS ---
    const valueLabels = mainGroupMerged.selectAll<SVGTextElement, BarData>('.value-label')
      .data(visibleData, d => d.id);

    valueLabels.exit().transition().duration(animDuration / 2).style('opacity', 0).remove();

    valueLabels.enter()
      .append('text').attr('class', 'value-label')
      .attr('x', d => xScale(d.value) + 6)
      .attr('y', (_d, i) => i * (barHeight + barGap) + barHeight / 2)
      .attr('dy', '0.35em')
      .attr('fill', 'rgba(255,255,255,0.85)')
      .attr('font-size', Math.max(10, barHeight * 0.34))
      .attr('font-weight', '500')
      .attr('font-family', 'Arial, sans-serif')
      .style('opacity', 0)
      .merge(valueLabels)
      .transition().duration(animDuration)
      .attr('x', d => Math.max(0, xScale(d.value)) + 6)
      .attr('y', (_d, i) => i * (barHeight + barGap) + barHeight / 2)
      .attr('font-size', Math.max(10, barHeight * 0.34))
      .style('opacity', 1)
      .text(d => formatNumber(d.value) + ' Mt');

  }, [timeIndex, instances, globalParameters, timeArray, showTitle, chartTitle, bgColor, barHeight, barGap, animDuration, currentYear]);

  const togglePlay = useCallback(() => {
    setIsPlaying(prev => !prev);
  }, []);

  return (
    <div
      ref={containerRef}
      style={{
        width: '100%',
        height: '100%',
        backgroundColor: bgColor,
        overflow: 'hidden',
        position: 'relative',
        fontFamily: 'Arial, Helvetica Neue, sans-serif'
      }}
    >
      <svg ref={svgRef} style={{ width: '100%', height: '100%' }} />
      <button
        onClick={togglePlay}
        style={{
          position: 'absolute',
          bottom: 12,
          left: 12,
          padding: '6px 16px',
          background: 'rgba(255,255,255,0.12)',
          color: '#fff',
          border: '1px solid rgba(255,255,255,0.25)',
          borderRadius: 6,
          cursor: 'pointer',
          fontSize: 13,
          fontFamily: 'Arial, sans-serif',
          backdropFilter: 'blur(4px)'
        }}
      >
        {isPlaying ? '⏸ Pause' : '▶ Play'}
      </button>
    </div>
  );
}

export class Asset extends DigoAsset {
  constructor() {
    super();
  }

  render() {
    return (
      <RacingBarChart
        instances={this.instances || []}
        globalParameters={this.globalParameters || {}}
        timeArray={this.timeArray || []}
      />
    );
  }
}

